export function findNearestBusStops(lat: number, lng: number, n = 3): { stop: BusStop; dist: number }[] {
  const R = 6371000
  return busStops
    .map(s => {
      const dLat = (s.lat - lat) * Math.PI / 180
      const dLng = (s.lng - lng) * Math.PI / 180
      const a = Math.sin(dLat/2)**2 + Math.cos(lat*Math.PI/180)*Math.cos(s.lat*Math.PI/180)*Math.sin(dLng/2)**2
      return { stop: s, dist: Math.round(R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))) }
    })
    .sort((a,b) => a.dist - b.dist)
    .slice(0, n)
}
